:root{
  --bg:#04060e;
  --ink:#eaf3ff;
  --muted:#8ea3c4;
  --cyan:#63f3ff;
  --blue:#4d8dff;
  --violet:#a06bff;
  --magenta:#ff5aa8;
  --lime:#9dff6a;
  --amber:#ffc857;
  --danger:#ff5470;
  --line:rgba(140,185,255,.15);
  --glass:rgba(14,22,42,.62);
}

*{box-sizing:border-box}

html,body{height:100%}

body{
  margin:0;
  background:
    radial-gradient(120% 85% at 50% -10%, #0b1630 0%, #060a17 45%, var(--bg) 78%);
  color:var(--ink);
  font-family:ui-rounded,"SF Pro Rounded","Segoe UI Variable Display","Segoe UI",system-ui,-apple-system,sans-serif;
  -webkit-font-smoothing:antialiased;
  overflow-x:hidden;
  overscroll-behavior:none;
  -webkit-user-select:none;
  user-select:none;
  -webkit-tap-highlight-color:transparent;
  touch-action:manipulation;
}

body::before{
  content:"";
  position:fixed;
  inset:0;
  background-image:
    linear-gradient(rgba(120,170,255,.055) 1px,transparent 1px),
    linear-gradient(90deg,rgba(120,170,255,.055) 1px,transparent 1px);
  background-size:52px 52px;
  -webkit-mask-image:radial-gradient(circle at 50% 34%,#000 0%,transparent 72%);
  mask-image:radial-gradient(circle at 50% 34%,#000 0%,transparent 72%);
  pointer-events:none;
  z-index:0;
}

.aurora{
  position:fixed;
  inset:-22%;
  z-index:0;
  pointer-events:none;
  background:
    radial-gradient(38% 34% at 16% 10%,rgba(56,189,248,.22),transparent 70%),
    radial-gradient(34% 30% at 86% 16%,rgba(160,107,255,.20),transparent 70%),
    radial-gradient(46% 40% at 52% 108%,rgba(255,90,168,.13),transparent 72%);
  filter:blur(26px);
  animation:drift 22s ease-in-out infinite alternate;
}

.bg-mark{
  position:fixed;
  right:-8vw;
  top:50%;
  z-index:0;
  transform:translateY(-50%) rotate(-8deg);
  font-size:clamp(360px,58vw,880px);
  font-weight:950;
  font-style:italic;
  letter-spacing:-.1em;
  line-height:.75;
  color:transparent;
  -webkit-text-stroke:1px rgba(99,243,255,.07);
  pointer-events:none;
  opacity:.75;
}

.fx{
  position:fixed;
  inset:0;
  z-index:30;
  pointer-events:none;
}

.app{
  position:relative;
  z-index:2;
  width:100%;
  max-width:800px;
  min-height:100dvh;
  margin:0 auto;
  padding:max(16px,env(safe-area-inset-top)) max(18px,env(safe-area-inset-right)) max(12px,env(safe-area-inset-bottom)) max(18px,env(safe-area-inset-left));
  display:flex;
  flex-direction:column;
}

/* ---------- HUD ---------- */

.hud{
  display:flex;
  align-items:center;
  gap:12px;
  width:100%;
}

.brand{
  display:flex;
  align-items:baseline;
  gap:5px;
  text-decoration:none;
  color:var(--ink);
  font-weight:900;
  font-size:21px;
  letter-spacing:-.04em;
  line-height:1;
  flex:0 0 auto;
}
.brand span{
  font-size:9px;
  font-weight:800;
  letter-spacing:.3em;
  color:var(--muted);
  transform:translateY(-1px);
}
.brand:hover{filter:brightness(1.15)}

.stats{
  display:flex;
  align-items:center;
  gap:6px;
  margin-left:auto;
}

.stat{
  min-width:58px;
  padding:5px 10px 6px;
  border-radius:12px;
  border:1px solid var(--line);
  background:linear-gradient(180deg,rgba(22,34,60,.66),rgba(9,15,30,.6));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.06);
  display:flex;
  flex-direction:column;
  gap:1px;
  text-align:center;
}
.stat span{
  font-size:7.5px;
  letter-spacing:.2em;
  color:var(--muted);
  font-weight:700;
}
.stat strong{
  font-size:14px;
  letter-spacing:.02em;
  font-variant-numeric:tabular-nums;
  color:#e9f3ff;
  font-weight:800;
}
.stat.time{min-width:64px}
.stat.time strong{color:var(--cyan);transition:color .2s}
.timebar.danger ~ .stage .stat.time strong,
.stat.time strong.danger{color:var(--danger)}

.icon-btn{
  flex:0 0 auto;
  width:38px;
  height:38px;
  border-radius:50%;
  display:grid;
  place-items:center;
  color:#b9cbe9;
  border:1px solid var(--line);
  background:rgba(14,22,42,.6);
  cursor:pointer;
  transition:color .2s,border-color .2s,transform .15s,background .2s;
}
.icon-btn:hover{color:var(--cyan);border-color:rgba(99,243,255,.45);background:rgba(20,34,60,.8)}
.icon-btn:active{transform:scale(.94)}
.icon-btn .slash{opacity:0;transition:opacity .2s}
.icon-btn.muted{color:var(--muted)}
.icon-btn.muted .wave{opacity:0}
.icon-btn.muted .slash{opacity:1}

.timebar{
  position:relative;
  width:100%;
  height:4px;
  margin-top:12px;
  border-radius:99px;
  background:rgba(120,160,230,.12);
  overflow:hidden;
  flex:0 0 auto;
}
.timefill{
  position:absolute;
  inset:0 auto 0 0;
  width:100%;
  border-radius:inherit;
  background:linear-gradient(90deg,var(--cyan),#7cf7c4 55%,var(--lime));
  box-shadow:0 0 14px rgba(99,243,255,.55);
  transition:width .1s linear,background .35s,box-shadow .35s;
}
.timebar.warn .timefill{
  background:linear-gradient(90deg,var(--amber),#ffe08a);
  box-shadow:0 0 14px rgba(255,200,87,.55);
}
.timebar.danger .timefill{
  background:linear-gradient(90deg,var(--danger),#ff9a6a);
  box-shadow:0 0 18px rgba(255,84,112,.7);
  animation:dangerPulse .85s ease-in-out infinite;
}

/* ---------- Stage ---------- */

.stage{
  flex:1;
  width:100%;
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  gap:clamp(12px,2.4vh,24px);
  padding:clamp(10px,2.5vh,24px) 0 6px;
  position:relative;
}

.zone-line{
  width:100%;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
  min-height:18px;
}

.zone-label{
  font-size:9.5px;
  font-weight:800;
  letter-spacing:.22em;
  color:#b9cbec;
  white-space:nowrap;
}
.zone-label em{
  font-style:normal;
  color:var(--muted);
  letter-spacing:.18em;
  font-weight:600;
}

.dots{
  display:flex;
  gap:5px;
}
.dots i{
  display:block;
  width:20px;
  height:4px;
  border-radius:99px;
  background:rgba(140,185,255,.18);
  transition:background .3s,box-shadow .3s,transform .3s;
}
.dots i.done{
  background:linear-gradient(90deg,var(--cyan),var(--blue));
  box-shadow:0 0 10px rgba(99,243,255,.55);
}
.dots i.current{
  background:rgba(99,243,255,.4);
  animation:dotPulse 1.8s ease-in-out infinite;
}

.streak{
  font-size:8.5px;
  font-weight:800;
  letter-spacing:.16em;
  color:var(--amber);
  padding:4px 8px;
  border-radius:99px;
  border:1px solid rgba(255,200,87,.32);
  background:rgba(255,200,87,.08);
  box-shadow:0 0 18px rgba(255,200,87,.12);
  white-space:nowrap;
}

.target{
  position:relative;
  width:clamp(72px,9.5vh,92px);
  aspect-ratio:1;
  border-radius:50%;
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  gap:0;
  border:1px solid rgba(99,243,255,.3);
  background:
    radial-gradient(circle at 50% 28%,rgba(99,243,255,.2),rgba(10,18,36,.78) 68%);
  box-shadow:
    0 0 44px rgba(99,243,255,.16),
    inset 0 0 26px rgba(99,243,255,.08),
    inset 0 1px 0 rgba(255,255,255,.14);
}
.target::before{
  content:"";
  position:absolute;
  inset:-7px;
  border-radius:50%;
  background:conic-gradient(from 0deg,transparent 0deg,var(--cyan) 70deg,transparent 150deg,var(--magenta) 250deg,transparent 330deg);
  opacity:.55;
  animation:spin 9s linear infinite;
  -webkit-mask:radial-gradient(farthest-side,transparent calc(100% - 2px),#000 calc(100% - 1px));
  mask:radial-gradient(farthest-side,transparent calc(100% - 2px),#000 calc(100% - 1px));
  pointer-events:none;
}
.target span{
  font-size:7px;
  font-weight:800;
  letter-spacing:.24em;
  color:var(--muted);
  transform:translateY(2px);
}
.target strong{
  font-size:clamp(30px,4.4vh,38px);
  line-height:1;
  font-weight:900;
  letter-spacing:-.05em;
  background:linear-gradient(160deg,#fff 8%,var(--cyan) 48%,var(--blue) 100%);
  -webkit-background-clip:text;
  background-clip:text;
  color:transparent;
  filter:drop-shadow(0 0 16px rgba(99,243,255,.38));
}

.board{
  display:flex;
  justify-content:center;
  align-items:center;
  gap:clamp(8px,2.2vw,16px);
  width:100%;
  min-height:calc(var(--tile) + 12px);
  --tile:min(clamp(68px,17vw,108px),13.5vh);
}

.tile{
  position:relative;
  width:var(--tile);
  height:var(--tile);
  padding:0;
  border-radius:23%;
  border:1px solid hsla(calc(190 + var(--i) * 24) 90% 70% / .28);
  background:
    radial-gradient(130% 120% at 18% 0%,hsla(calc(192 + var(--i) * 26) 95% 62% / .34),transparent 56%),
    linear-gradient(158deg,rgba(38,54,94,.92),rgba(8,13,27,.97));
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.22),
    inset 0 -18px 30px rgba(0,0,0,.35),
    0 16px 34px -14px rgba(0,0,0,.95),
    0 0 0 1px rgba(99,243,255,.04);
  color:#f2f8ff;
  font-family:inherit;
  font-size:calc(var(--tile) * .4);
  font-weight:900;
  letter-spacing:-.05em;
  font-variant-numeric:tabular-nums;
  display:grid;
  place-items:center;
  cursor:pointer;
  transition:transform .16s cubic-bezier(.2,.9,.3,1.4),box-shadow .22s,border-color .22s,filter .22s;
  -webkit-appearance:none;
  appearance:none;
  outline:none;
}
.tile::after{
  content:"";
  position:absolute;
  inset:0;
  border-radius:inherit;
  background:linear-gradient(180deg,rgba(255,255,255,.16),transparent 42%);
  pointer-events:none;
}
.tile .frac{
  font-size:.72em;
  letter-spacing:-.04em;
  display:inline-flex;
  align-items:center;
  gap:1px;
}
.tile:hover{filter:brightness(1.12);transform:translateY(-2px)}
.tile:active{transform:translateY(0) scale(.97)}

.tile.sel{
  border-color:rgba(99,243,255,.9);
  transform:translateY(-7px) scale(1.05);
  box-shadow:
    0 0 0 2px rgba(99,243,255,.55),
    0 0 46px rgba(99,243,255,.34),
    0 22px 40px -14px rgba(0,0,0,.95);
  z-index:2;
}
.tile.second{
  border-color:rgba(255,90,168,.7);
  box-shadow:
    0 0 0 2px rgba(255,90,168,.35),
    0 0 32px rgba(255,90,168,.22),
    0 18px 36px -14px rgba(0,0,0,.95);
}
.tile.hint{
  animation:hintPulse 1s ease-in-out infinite;
  border-color:rgba(157,255,106,.8);
}
.tile.pop{animation:tilePop .32s cubic-bezier(.2,1.4,.4,1)}
.tile.merging{
  transform:scale(1.09);
  border-color:rgba(99,243,255,.95);
  box-shadow:0 0 52px rgba(99,243,255,.45);
}

.expression{
  min-height:20px;
  margin:0;
  font-size:13px;
  letter-spacing:.03em;
  font-weight:600;
  color:#8fa5c8;
  font-variant-numeric:tabular-nums;
  text-align:center;
}
.expression b{color:var(--cyan);font-weight:800}
.expression .eq{color:var(--muted);margin:0 3px}

.operators{
  display:flex;
  justify-content:center;
  gap:clamp(10px,3vw,16px);
  width:100%;
}

.op{
  width:clamp(52px,13.5vw,64px);
  aspect-ratio:1;
  border-radius:19px;
  border:1px solid var(--line);
  background:linear-gradient(180deg,rgba(32,48,82,.86),rgba(10,17,33,.94));
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.14),
    0 12px 24px -12px rgba(0,0,0,.9);
  color:#dce9ff;
  font-family:inherit;
  font-size:clamp(23px,6vw,28px);
  font-weight:600;
  line-height:1;
  display:grid;
  place-items:center;
  cursor:pointer;
  transition:transform .14s,border-color .2s,box-shadow .2s,color .2s,opacity .2s;
  -webkit-appearance:none;
  appearance:none;
  outline:none;
}
.op:hover{border-color:rgba(99,243,255,.45);color:var(--cyan);transform:translateY(-2px);box-shadow:0 0 28px rgba(99,243,255,.16),inset 0 1px 0 rgba(255,255,255,.16)}
.op:active{transform:translateY(0) scale(.96)}
.op.dim{opacity:.48}
.op.chosen{
  border-color:rgba(99,243,255,.8);
  color:#04121c;
  background:linear-gradient(180deg,var(--cyan),#7bd9ff);
  box-shadow:0 0 30px rgba(99,243,255,.4);
}
.op:disabled{opacity:.3;cursor:not-allowed}

.actions{
  display:flex;
  justify-content:center;
  gap:8px;
  width:100%;
  flex-wrap:wrap;
}

.action{
  padding:9px 14px;
  border-radius:999px;
  border:1px solid var(--line);
  background:rgba(14,24,46,.55);
  color:#b9cbe9;
  font-family:inherit;
  font-size:9.5px;
  font-weight:800;
  letter-spacing:.15em;
  text-transform:uppercase;
  cursor:pointer;
  transition:color .2s,border-color .2s,background .2s,transform .15s,opacity .2s;
  -webkit-appearance:none;
  appearance:none;
}
.action:hover{color:var(--cyan);border-color:rgba(99,243,255,.4);background:rgba(22,38,66,.78)}
.action:active{transform:scale(.96)}
.action:disabled{opacity:.32;cursor:not-allowed;transform:none}

.message{
  min-height:18px;
  margin:0;
  font-size:11.5px;
  letter-spacing:.04em;
  color:var(--muted);
  text-align:center;
  transition:color .2s;
  max-width:34em;
}
.message.warn{color:var(--amber)}
