Now game.js. Write carefully. Consider bugs.

Full code:

```js
(() => {
'use strict';

/* ---------- utils ---------- */
const $=(sel,root=document)=>root.querySelector(sel);
const clamp=(n,a,b)=>Math.min(b,Math.max(a,n));
const pad2=n=>String(n).padStart(2,'0');

function gcd(a,b){a=Math.abs(a);b=Math.abs(b);while(b){const t=a%b;a=b;b=t;}return a||1;}
function rat(n,d=1){ if(d<0){n=-n;d=-d;} const g=gcd(n,d)||1; return {n:n/g,d:d/g}; }
const V0=rat(0);
function vEq(a,b){return a.n===b.n&&a.d===b.d;}
function vAdd(a,b){return rat(a.n*b.d+b.n*a.d,a.d*b.d);}
function vSub(a,b){return rat(a.n*b.d-b.n*a.d,a.d*b.d);}
function vMul(a,b){return rat(a.n*b.n,a.d*b.d);}
function vDiv(a,b){return b.n===0?null:rat(a.n*b.d,a.d*b.n);}
function fmt(v){return v.d===1?String(v.n):`${v.n}/${v.d}`;}

const OPS=[
 {sym:'+',fn:vAdd},
 {sym:'−',fn:vSub},
 {sym:'×',fn:vMul},
 {sym:'÷',fn:vDiv},
];
const opBySym=sym=>OPS.find(o=>o.sym===sym);
```

solve:
```js
function solve(vals, ops=OPS){
 if(vals.length===1) return vals[0].n===24*vals[0].d?[]:null;
 for(let i=0;i<vals.length;i++){
  for(let j=0;j<vals.length;j++){
   if(i===j) continue;
   const a=vals[i],b=vals[j];
   for(const op of ops){
    if((op.sym==='+'||op.sym==='×')&&j<i) continue; // avoid duplicate commutative order
    const r=op.fn(a,b);
    if(!r) continue;
    const rest=[];
    for(let k=0;k<vals.length;k++) if(k!==i&&k!==j) rest.push(vals[k]);
    rest.push(r);
    const sub=solve(rest,ops);
    if(sub) return [{a,b,op:op.sym,res:r},...sub];
   }
  }
 }
 return null;
}
```
Wait: allowing ordered pairs for all ops creates duplicate work but fine; commutative dedupe via j<i skip for +/× keeps correctness. For −/÷ both orders explored. Good.

For zone1/2 solver excluding ÷: `OPS.filter(o=>o.sym!=='÷')`.

Generation:
```js
function makePuzzle(zone, first){
 if(first) return [6,4,2,1].map(n=>rat(n));
 const max=zone<=1?6:zone<=2?9:zone<=3?11:13;
 const ops=zone<=2?OPS.filter(o=>o.sym!=='÷'):OPS;
 for(let tries=0;tries<500;tries++){
   const vals=[...Array(4)].map(()=>rat(1+Math.floor(Math.random()*max)));
   if(new Set(vals.map(v=>v.n)).size<2) continue;
   if(solve(vals,ops)) return vals;
 }
 return [6,4,2,1].map(n=>rat(n));
}
```
Zone1 fallback fine. Zone 3+ with division allowed; fallback [6,4,2,1] fine.

Concern: zone1 no-division puzzles might rarely be solvable with just +×−? Actually many are. Fine.

